/// Apply Poison to all opponents, then trigger each target's Poison.
/// Source: v0.111.0 Models.Cards/Outbreak.cs and Models.Powers/PoisonPower.cs.
pub(crate) fn play_outbreak(state: &mut CombatState, _t: Option<CreatureUid>) -> EffectResult {
    let amount = if current_card_upgraded(state) { 12 } else { 9 };
    apply_power_to_all_enemies(state, PowerKind::Poison, amount);
    let enemies = state.active_enemy_uids();
    for target in enemies {
        let listener = state
            .creatures
            .iter()
            .find(|c| c.id == target.0)
            .and_then(|c| {
                c.powers.iter().copied().find(|uid| {
                    state
                        .powers
                        .get_by_id(uid.0)
                        .is_some_and(|p| p.kind == PowerKind::Poison)
                })
            });
        if let Some(uid) = listener {
            if let Some(effects) = sts2_core::hooks::after_side_turn_start(
                state,
                sts2_core::hooks::ListenerRef::Power(uid),
                &sts2_core::hooks::TurnSideCtx {
                    side: sts2_core::Side::Enemy,
                },
            ) {
                sts2_core::hooks::apply_effects(state, &effects);
            }
        }
    }
    EffectResult::Resolved
}

